body[data-sty="constructivism"] .btn-cook {
  display: inline-block;
  padding: 0.9em 1.6em 0.9em 1.2em;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #f5efdd;
  background: #c8102e;
  border: 3px solid #111111;
  box-shadow: 6px 6px 0 #111111;
  clip-path: polygon(0 0, 100% 0, calc(100% - 18px) 100%, 0 100%);
  cursor: pointer;
}
body[data-sty="constructivism"] .btn-cook:hover {
  background: #111111;
  color: #f5efdd;
  box-shadow: 6px 6px 0 #c8102e;
}
body[data-sty="constructivism"] .btn-cook:active {
  transform: translate(3px, 3px);
  box-shadow: 3px 3px 0 #111111;
}

body[data-sty="constructivism"] .sty-tex.tex-constructivism-1 {
  background-color: transparent;
  background-image:
    linear-gradient(180deg, #c8102e 0 14px, transparent 14px),
    linear-gradient(90deg, #111111 0 10px, transparent 10px),
    linear-gradient(0deg, #111111 0 10px, transparent 10px),
    linear-gradient(-45deg, #c8102e 0 22px, transparent 22px);
  background-position: top left, bottom left, top right, bottom right;
  background-repeat: no-repeat;
  background-size: 38% 100%, 100% 100%, 100% 100%, 100% 100%;
  border: 3px solid #111111;
}

@media (prefers-reduced-motion: no-preference) {
  @keyframes constructivism-thrust {
    0% { transform: translate(0, 0) rotate(0deg); opacity: 1; }
    50% { transform: translate(8px, -8px) rotate(-1.5deg); opacity: 0.92; }
    100% { transform: translate(0, 0) rotate(0deg); opacity: 1; }
  }
  body[data-sty="constructivism"] .anim-constructivism-1 {
    animation: constructivism-thrust 4s ease-in-out infinite alternate;
  }
}

body[data-sty="constructivism"] .orn-constructivism-1 {
  position: absolute;
  width: 140px;
  height: 18px;
  background: #c8102e;
  transform: rotate(-45deg);
  transform-origin: left center;
}
body[data-sty="constructivism"] .orn-constructivism-1::after {
  content: "";
  position: absolute;
  right: -14px;
  top: 50%;
  width: 34px;
  height: 34px;
  margin-top: -17px;
  background: #111111;
  border-radius: 50%;
}
